"""Portable local video/head comparison and honest conditional accuracy report."""
import hashlib
from html import escape
import json
from pathlib import Path
from scripts.video_truth_inventory import ROOT,OUT,save
from app.experimental.video_onset_bias import head_onsets


def read(p):return json.loads(p.read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()


def main():
    frozen=read(OUT/'conditional_onset_calibration/frozen_candidates.json')
    measured=read(OUT/'conditional_onset_calibration/evaluation.json')
    source=ROOT/'evidence/learned_archive_integration_20261018/archive_1/result.json'
    assert sha(source)==frozen['source_prediction_sha256']
    estimate=read(source)['estimated_signals']
    offset=(estimate['schedule_base_timestamp_ms']-frozen['nominal_video_epoch_ms'])/1000
    events=[]
    for color in ('green','red'):
        for t in head_onsets(estimate,'N',color.upper()):
            events.append(dict(time=t+offset,color=color.upper(),bias=frozen['candidates'][color]['bias_s']))
    events.sort(key=lambda e:e['time'])
    truth=[]
    for color,file in [('GREEN','video_only_truth_sealed.json'),('RED','video_red_truth_sealed.json')]:
        for window in read(OUT/'sverdlovsky'/file)['windows']:
            for row in window['transitions']:truth.append(dict(color=color,window=window['window'],**row))
    payload=dict(events=events,truth=truth,
        model_range_s=[offset,read(source)['recording_duration_s']+offset],
        source_bytes=3089546077,
        source_name='len_sverdl 2025-02-27T10_00_00_2025-02-27T12_00_00.mp4',
        nominal_clock_base_ms=frozen['nominal_video_epoch_ms'],production_enabled=False,
        clock_verified=False,other_heads_calibrated=False)
    save(OUT/'comparison_data.json',payload)
    table=''.join(f"<tr><td>{r['window']}</td><td>{r['color']}</td><td>{r['bracket_s'][0]:.6f}–{r['bracket_s'][1]:.6f}</td><td><button data-seek='{sum(r['bracket_s'])/2:.6f}'>Показать</button> <a href='{escape(r['before']['file'])}'>до</a> / <a href='{escape(r['after']['file'])}'>после</a></td></tr>" for r in sorted(truth,key=lambda r:r['bracket_s'][0]))
    page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Свердловский — видео и задержка модели</title><style>body{font:16px/1.5 system-ui;background:#111720;color:#eef3ff;max-width:1250px;margin:24px auto;padding:0 16px}a{color:#9ccdff}button,input{font:inherit;margin:5px;padding:7px}video{width:100%;max-height:65vh;background:#000}canvas{width:360px;max-width:100%;image-rendering:pixelated;background:#000}.row{display:flex;gap:20px;flex-wrap:wrap}.card{background:#263144;padding:16px;flex:1;min-width:210px;border-radius:10px}.warning{padding:16px;border:1px solid #c5a245;background:#302917}strong.state{font-size:26px}.GREEN{color:#40e791}.RED{color:#ff7185}.UNKNOWN{color:#b9c9db}table{border-collapse:collapse;font-size:14px;width:100%}td,th{border:1px solid #475369;padding:8px}.scroll{overflow:auto}small{color:#bfccdd}</style><h1>Видимый светофор: видео и прогноз</h1><p class="warning">Эксперимент при предположении, что часы JSON совпадают с часами камеры. Эта связь пока не подтверждена по одному и тому же автомобилю. Поправка ниже объединяет возможный сдвиг часов и запаздывание модели. В приложение она не включена. Сравнивается только основной видимый сигнал H1 (предположительно N).</p><p>Выберите исходный MP4 Свердловского. Он читается браузером локально и никуда не загружается.</p><input id="file" type="file" accept="video/mp4"><p id="status">Видео не выбрано.</p><video id="video" controls preload="metadata"></video><p>Реальное время показанного кадра: <b id="pts">—</b>; часы по номинальному началу: <b id="clock">—</b>.</p><button id="cal">Участок настройки: 900 с</button><button id="test">Участок проверки: 2700 с</button><button id="back">−0.1 с</button><button id="forward">+0.1 с</button><div class="row"><div class="card"><h2>Светофор в кадре</h2><canvas id="zoom" width="360" height="240"></canvas><p>Увеличение исходных пикселей. Цвет проверяется по самому видео; отдельные тёмные кадры могут быть следствием съёмки светодиодов.</p></div><div class="card"><h2>Прогноз до поправки</h2><strong id="before" class="state UNKNOWN">UNKNOWN</strong><p>Оценка по транспортным данным.</p></div><div class="card"><h2>Условная поправка</h2><strong id="after" class="state UNKNOWN">UNKNOWN</strong><p>Зелёный раньше на 3.898 с, красный — на 4.939 с. Значения получены только на первом участке.</p></div></div><p>Жёлтые/мигающие состояния и другие светофоры здесь не оцениваются. Прогноз доступен только в интервале выбранного JSON первого часа. Кнопки ±0.1 с задают перемотку, а не обещают шаг ровно в один исходный кадр.</p><h2>Отметки по кадрам</h2><div class="scroll"><table><tr><th>Участок</th><th>Включение</th><th>Интервал PTS, с</th><th>Кадры</th></tr>'''+table+'''</table></div><p><a href="report.html">Результаты, даты, JSON и ограничения</a></p><script>const DATA=__DATA__;const video=document.getElementById('video'),status=document.getElementById('status'),canvas=document.getElementById('zoom'),ctx=canvas.getContext('2d');let objectUrl=null;ctx.imageSmoothingEnabled=false;
function stateAt(t,corrected){if(t<DATA.model_range_s[0]||t>=DATA.model_range_s[1])return 'UNKNOWN';let state='UNKNOWN';const events=DATA.events.map(e=>({time:e.time-(corrected?e.bias:0),color:e.color})).sort((a,b)=>a.time-b.time);for(const e of events){if(e.time>t)break;state=e.color;}return state;}
function render(t){document.getElementById('pts').textContent=t.toFixed(6)+' с';document.getElementById('clock').textContent=new Date(DATA.nominal_clock_base_ms+t*1000).toLocaleString('ru-RU',{timeZone:'Asia/Yekaterinburg'})+' (привязка предполагается)';for(const [id,corrected] of [['before',false],['after',true]]){const s=stateAt(t,corrected),el=document.getElementById(id);el.textContent=s;el.className='state '+s;}if(video.readyState>=2)ctx.drawImage(video,1940,864,180,120,0,0,360,240);}
function frame(now,metadata){render(metadata.mediaTime);video.requestVideoFrameCallback(frame);}if(video.requestVideoFrameCallback)video.requestVideoFrameCallback(frame);video.addEventListener('seeked',()=>render(video.currentTime));video.addEventListener('timeupdate',()=>render(video.currentTime));
document.getElementById('file').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(file.size!==DATA.source_bytes){status.textContent='Размер отличается от проверенного видео. Выберите исходный файл Свердловского.';return;}if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);video.src=objectUrl;status.textContent='Локальное видео выбрано. Синхронизация часов остаётся предположением.';});
function seek(t){if(!video.src){status.textContent='Сначала выберите MP4 выше.';return;}video.pause();video.currentTime=Math.max(0,t);}
document.getElementById('cal').onclick=()=>seek(900);document.getElementById('test').onclick=()=>seek(2700);document.getElementById('back').onclick=()=>seek(video.currentTime-.1);document.getElementById('forward').onclick=()=>seek(video.currentTime+.1);document.querySelectorAll('[data-seek]').forEach(b=>b.onclick=()=>seek(Number(b.dataset.seek)));window.__VIDEO_REVIEW__={stateAt,DATA,seek};</script></html>'''
    page=page.replace('__DATA__',json.dumps(payload,ensure_ascii=False).replace('</','<\\/'))
    with (OUT/'visible_head_comparison.html').open('x',encoding='utf8',newline='\n') as f:f.write(page)
    inventories={s:read(OUT/'archive_inventory'/s/'summary.json') for s in ('sverdlovsky','enthusiasts')}
    members=''
    for site,inventory in inventories.items():
        for row in inventory['members']:
            members+=f"<tr><td>{escape(row['member'])}</td><td>{row['min_detection_utc5']}</td><td>{row['max_detection_utc5']}</td><td>{row['tracks']}</td></tr>"
    metric_rows=''
    for color,row in measured['results'].items():
        old,new=row['before'],row['after']
        metric_rows+=f"<tr><td>{color}</td><td>{old['truth_onsets']}</td><td>{old['mean_absolute_midpoint_error_s']:.3f} → {new['mean_absolute_midpoint_error_s']:.3f} с</td><td>{new['mean_distance_to_truth_bracket_s']:.3f} с</td><td>{new['within_0_5s_of_bracket']}/{new['truth_onsets']}</td></tr>"
    report='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Проверка двух видео — Traffic Phase</title><style>body{font:17px/1.55 system-ui;max-width:1150px;margin:30px auto;padding:0 18px;background:#111720;color:#edf4ff}a{color:#9ccdff}table{border-collapse:collapse;font-size:14px;width:100%}td,th{border:1px solid #475369;padding:9px}.scroll{overflow-x:auto}img{max-width:100%;height:auto}.note{padding:16px;background:#302917;border:1px solid #c5a245}li{margin:9px 0}</style><h1>Видео подтверждает видимое запаздывание</h1><p>Для Свердловского, при прямой привязке JSON к часам камеры, оценка зелёного запаздывает примерно на 3.9 с, красного — на 4.9 с. Два постоянных сдвига вычислены на PTS900–1500с. На отдельном участке PTS2700–3300с они проверены без повторного подбора.</p><p class="note">Ключевое ограничение: абсолютная связь video PTS ↔ detections[].millis ещё не подтверждена независимой машиной/кадром. Поправка объединяет задержку модели и возможное расхождение часов. Эти числа нельзя выдавать за доказанную физическую точность или переносить в приложение как проверенную калибровку. Production не менялся.</p><p><a href="visible_head_comparison.html">Открыть исходное видео рядом с прогнозом до/после условной поправки</a>. На странице выберите исходный MP4 Свердловского; файл остаётся локальным.</p><h2>Дата и время внизу слева</h2><ul><li>Свердловский: 27.02.2025 09:59:55 на первом кадре PTS0; на PTS900 — 10:14:55; на PTS2700.033333 — 10:44:55; на PTS3600 — 10:59:55.</li><li>Энтузиастов: 05.10.2024 11:59:58 на PTS0; на PTS900.033333 — 12:14:58; на PTS2700 — 12:44:58; на PTS3600 — 12:59:58.</li></ul><p>Видимые часы секундные. Время соседних исходных кадров позволяет задавать доли секунды в координатах видео, но точность абсолютного совмещения с JSON этим не доказывается.</p><details><summary>Исходные пиксели часов Свердловского</summary><img src="sverdlovsky/clock_sheet.png"></details><details><summary>Исходные пиксели часов Энтузиастов</summary><img src="enthusiasts/clock_sheet.png"></details><h2>Найденные данные: прочитаны все 9 JSON двух ZIP</h2><div class="scroll"><table><tr><th>JSON</th><th>Начало detections, UTC+5</th><th>Конец detections, UTC+5</th><th>Треков</th></tr>'''+members+'''</table></div><p>Свердловскому соответствуют прежде всего JSON17_..._10 и17_..._11; часть треков пересекает границу часа. JSON12 содержит в основном час после конца видео. Времена не выводятся только из имени файла: каждая detection прочитана потоково, CRC и SHA256 JSON сохранены.</p><p>Энтузиастов: происхождение видео из этого архива подтверждено поставщиком и полным SHA256 ранее. Но дата экспорта23.02.2025 отличается от даты камеры05.10.2024. Полный экспорт занимает около4ч40м13с по своей шкале, видео —5ч14с. Это может означать неполное покрытие или различие шкал времени; равенство начала/скорости часов пока не установлено. По этой паре ошибка модели в секундах не рассчитана.</p><h2>Метки по самому видео</h2><p>Свердловский: 12 включений основного зелёного, 10 уверенных включений красного; два красных перехода оставлены неразрешёнными. Энтузиастов: 12 включений зелёного, в том числе четыре с тусклой линзой/LED alias, для которых сохранены более широкие или менее уверенные интервалы. Модель не использовалась для выбора видеометок.</p><p>У Свердловского 11 из12 зелёных интервалов уже секунды; один намеренно оставлен шириной2.467с, поскольку отдельные тёмные кадры не доказывают выключение светодиодного сигнала. Никакого обещания одинаковой миллисекундной точности всем меткам нет.</p><p><a href="sverdlovsky/video_only_truth_sealed.json">Зелёные Свердловского JSON</a> · <a href="sverdlovsky/video_red_truth_sealed.json">Красные и пропуски JSON</a> · <a href="enthusiasts/video_only_truth_sealed.json">Зелёные Энтузиастов JSON</a></p><h2>Условная проверка на втором участке Свердловского</h2><div class="scroll"><table><tr><th>Включение</th><th>Уверенных меток</th><th>MAE до → после, по серединам интервалов</th><th>Расстояние до интервала после</th><th>В пределах0.5с от интервала</th></tr>'''+metric_rows+'''</table></div><p>У широкого интервала середина не является известным моментом переключения; MAE по серединам приведена отдельно от расстояния до интервала. Неопределённость JSON/video clock и exposure сюда не включена. Один несопоставленный прогноз красного соответствует неразрешённому видеоциклу и не объявляется ложным срабатыванием. Другие светофоры и вся двухчасовая история не проверялись.</p><h2>Что требуется для настоящей калибровки</h2><p>Подтвердить стороны света/назначение видимой лампы и установить независимую связь кадров с JSON по одинаковым машинам, без подгонки по светофорным циклам. Для Энтузиастов нужны пары в разных частях видео, чтобы проверить ещё и скорость/неполноту временной шкалы. Старые непрошедшие vehicle-fit проверки сохранены; их сдвиги не выданы за подтверждённые.</p><p><a href="conditional_onset_calibration/frozen_candidates.json">Зафиксированные поправки и предположения</a> · <a href="conditional_onset_calibration/evaluation.json">Все контрольные пары</a> · <a href="clock_readouts.json">Чтения часов</a></p></html>'''
    with (OUT/'report.html').open('x',encoding='utf8',newline='\n') as f:f.write(report)
    print('PASS: portable video/head comparison and source/accuracy report written')


if __name__=='__main__':main()
